<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { automationApi } from '@/api/automation'

const tasks=ref<any[]>([]),templates=ref<any[]>([]),runs=ref<any[]>([]),active=ref<any>(null),loading=ref(true),open=ref(false),running=ref('')
const form=reactive({name:'',task_type:'daily_report',query:'',timezone:'Asia/Shanghai',scheduleKind:'daily',time:'09:00',minutes:60,cost_limit:1,channels:['in_app'] as string[]})
async function load(){loading.value=true;try{[tasks.value,templates.value]=await Promise.all([automationApi.tasks(),automationApi.templates()]);if(active.value){active.value=tasks.value.find(x=>x.id===active.value.id)||null;if(active.value)runs.value=await automationApi.runs(active.value.id)}}finally{loading.value=false}}
async function selectTask(task:any){active.value=task;runs.value=await automationApi.runs(task.id)}
async function create(){const schedule=form.scheduleKind==='daily'?{kind:'daily',time:form.time}:{kind:'interval',minutes:form.minutes};const template=templates.value.find(x=>x.id===form.task_type);await automationApi.createTask({name:form.name,task_type:form.task_type,config:{query:form.query,channels:form.channels},schedule,timezone:form.timezone,cost_limit:form.cost_limit,estimated_cost:template?.estimated_cost||0,max_retries:3,max_concurrency:1});open.value=false;ElMessage.success('任务已创建');await load()}
async function action(task:any,name:'pause'|'resume'|'cancel'|'confirm'){await automationApi.taskAction(task.id,name);ElMessage.success(name==='confirm'?'高风险操作已确认':'任务状态已更新');await load()}
async function run(task:any){running.value=task.id;try{const result=await automationApi.runTask(task.id);ElMessage[result.status==='succeeded'?'success':'warning'](`运行状态：${result.status}`);await selectTask(task);await load()}finally{running.value=''}}
async function retry(run:any){await automationApi.retryRun(run.id);ElMessage.success('已创建重试运行');if(active.value)runs.value=await automationApi.runs(active.value.id)}
function statusName(value:string){return({active:'运行中',paused:'已暂停',cancelled:'已取消',succeeded:'成功',running:'执行中',retrying:'等待重试',dead_letter:'死信',blocked:'已阻止',awaiting_confirmation:'待确认'} as any)[value]||value}
onMounted(load)
</script>
<template><main class="tasks-page"><header><div><small>AGENT AUTOMATION</small><h1>任务中心</h1><p>定时执行、运行日志、失败重试与成本控制集中管理。</p></div><button @click="open=true"><el-icon><Plus /></el-icon>新建任务</button></header><section class="task-layout"><div v-loading="loading" class="task-list"><article v-for="task in tasks" :key="task.id" :class="{active:active?.id===task.id}" @click="selectTask(task)"><div class="task-icon"><el-icon><Timer /></el-icon></div><div><h2>{{task.name}}</h2><p>{{task.task_type}} · {{task.timezone}}</p><span :class="`status ${task.status}`">{{statusName(task.status)}}</span><span v-if="task.confirmation_status==='pending'" class="risk">待风险确认</span></div><div class="next"><small>下次执行</small><time>{{task.next_run_at?new Date(task.next_run_at).toLocaleString():'—'}}</time></div><div class="actions" @click.stop><button title="立即运行" :disabled="running===task.id" @click="run(task)"><el-icon><VideoPlay /></el-icon></button><button v-if="task.status==='active'" title="暂停" @click="action(task,'pause')"><el-icon><VideoPause /></el-icon></button><button v-if="task.status==='paused'" title="恢复" @click="action(task,'resume')"><el-icon><RefreshRight /></el-icon></button><button v-if="task.confirmation_status==='pending'" title="确认高风险操作" @click="action(task,'confirm')"><el-icon><Warning /></el-icon></button></div></article><div v-if="!loading&&!tasks.length" class="empty"><el-icon><Timer /></el-icon><h2>还没有自动任务</h2><p>从日报、关键词监控或企业监控模板开始。</p></div></div><aside><template v-if="active"><header><div><small>RUN HISTORY</small><h2>{{active.name}}</h2></div><span>上限 ¥{{active.cost_limit.toFixed(2)}} / 次</span></header><div class="guard"><div><span>预计成本</span><b>¥{{active.estimated_cost.toFixed(2)}}</b></div><div><span>并发上限</span><b>{{active.max_concurrency}}</b></div><div><span>失败重试</span><b>{{active.max_retries}}</b></div></div><div class="runs"><article v-for="item in runs" :key="item.id"><header><span :class="`status ${item.status}`">{{statusName(item.status)}}</span><time>{{new Date(item.created_at).toLocaleString()}}</time></header><p v-if="item.error_message">{{item.error_message}}</p><dl><div><dt>尝试</dt><dd>{{item.attempt}}</dd></div><div><dt>成本</dt><dd>¥{{item.cost.toFixed(2)}}</dd></div><div v-if="item.diagnostic_id"><dt>诊断 ID</dt><dd>{{item.diagnostic_id}}</dd></div></dl><details v-if="item.logs.length"><summary>运行日志</summary><pre>{{item.logs.map((x:any)=>`${x.at}  ${x.message}`).join('\n')}}</pre></details><button v-if="['dead_letter','failed','blocked'].includes(item.status)" @click="retry(item)">重试</button><a v-if="item.output.report_id" :href="`/reports/${item.output.report_id}`">打开报告</a></article><div v-if="!runs.length" class="mini-empty">尚无运行记录</div></div></template><div v-else class="aside-empty"><el-icon><List /></el-icon><p>选择任务查看运行记录与日志</p></div></aside></section>
<div v-if="open" class="overlay" @click.self="open=false"><form @submit.prevent="create"><header><h2>创建自动任务</h2><button type="button" @click="open=false"><el-icon><Close /></el-icon></button></header><label>模板<select v-model="form.task_type" @change="form.name=templates.find(x=>x.id===form.task_type)?.name||''"><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>任务名称<input v-model="form.name" required/></label><label v-if="form.task_type!=='daily_report'">监控查询<input v-model="form.query" required/></label><div class="grid"><label>执行方式<select v-model="form.scheduleKind"><option value="daily">每天</option><option value="interval">固定间隔</option></select></label><label v-if="form.scheduleKind==='daily'">时间<input v-model="form.time" type="time"/></label><label v-else>分钟<input v-model.number="form.minutes" type="number" min="5"/></label></div><div class="grid"><label>时区<select v-model="form.timezone"><option>Asia/Shanghai</option><option>UTC</option><option>America/New_York</option></select></label><label>单次成本上限<input v-model.number="form.cost_limit" type="number" min="0" step="0.01"/></label></div><fieldset><legend>投递渠道</legend><label><input v-model="form.channels" type="checkbox" value="in_app"/>站内</label><label><input v-model="form.channels" type="checkbox" value="email"/>邮件</label><label><input v-model="form.channels" type="checkbox" value="webhook"/>Webhook</label></fieldset><footer><button type="button" @click="open=false">取消</button><button class="primary">创建任务</button></footer></form></div></main></template>
<style scoped>.tasks-page{min-height:100vh;padding:36px clamp(18px,3vw,52px);color:#17231f;background:#f2f5f4}.tasks-page>header{display:flex;align-items:end;justify-content:space-between;padding-bottom:24px;border-bottom:1px solid #cbd7d2}.tasks-page>header small{color:#167f76;font-weight:800}.tasks-page h1{margin:7px 0;font:650 40px Georgia,"Songti SC",serif}.tasks-page>header p{margin:0;color:#6c7e77}.tasks-page>header button,.primary{height:40px;padding:0 14px;border:0;border-radius:5px;color:white;background:#183129}.task-layout{margin-top:20px;display:grid;grid-template-columns:minmax(520px,1.25fr) minmax(320px,.75fr);gap:14px}.task-list,aside{min-height:500px;border:1px solid #cbd7d2;border-radius:7px;background:#fff}.task-list>article{min-height:100px;padding:15px;display:grid;grid-template-columns:50px 1fr 150px auto;gap:12px;align-items:center;border-top:1px solid #e0e7e4;cursor:pointer}.task-list>article:first-child{border:0}.task-list>article.active{background:#edf5f2}.task-icon{width:40px;height:40px;border-radius:5px;display:grid;place-items:center;color:#167f76;background:#dcece8}.task-list h2{margin:0;font-size:16px}.task-list p{margin:6px 0;color:#71817b;font-size:10px}.status,.risk{margin-right:5px;padding:3px 6px;border-radius:3px;color:#66756f;background:#e8edeb;font-size:9px}.status.active,.status.succeeded{color:#08775a;background:#dff3ec}.status.retrying,.status.awaiting_confirmation,.risk{color:#9a5a0b;background:#fff0d8}.status.dead_letter,.status.blocked{color:#aa3434;background:#fbe4e3}.next small,.next time{display:block}.next small{color:#87938f;font-size:9px}.next time{margin-top:6px;font-size:10px}.actions{display:flex;gap:5px}.actions button{width:32px;height:32px;border:1px solid #ccd8d3;border-radius:4px;background:#fff}aside{padding:17px;overflow:auto}aside>header{display:flex;align-items:start;justify-content:space-between}aside h2{margin:4px 0}aside header small{color:#168078;font-size:9px}aside header>span{color:#6d7e77;font-size:10px}.guard{margin:15px 0;display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #d5dfdb}.guard div{padding:11px;border-left:1px solid #dce4e1}.guard div:first-child{border:0}.guard span,.guard b{display:block}.guard span{font-size:9px;color:#7b8984}.guard b{margin-top:5px}.runs>article{padding:13px 0;border-top:1px solid #dce4e1}.runs article header{display:flex;justify-content:space-between}.runs time{color:#7c8a85;font-size:9px}.runs p{color:#a33b3b;font-size:11px}.runs dl{display:flex;gap:12px}.runs dl div{display:flex;gap:4px;font-size:9px}.runs dd{margin:0}.runs pre{overflow:auto;padding:8px;background:#17231f;color:#dcece7;font-size:9px}.runs button,.runs a{margin-right:6px;padding:6px 9px;border:1px solid #cbd7d2;color:#16776e;background:#fff;font-size:10px}.aside-empty,.empty{min-height:460px;display:grid;place-items:center;align-content:center;text-align:center;color:#7a8984}.aside-empty .el-icon,.empty .el-icon{font-size:40px}.overlay{position:fixed;inset:0;z-index:600;display:grid;place-items:center;padding:15px;background:rgba(10,27,21,.44)}.overlay form{width:min(560px,100%);padding:22px;border-radius:7px;background:#fff}.overlay form>header,.overlay footer{display:flex;justify-content:space-between;align-items:center}.overlay h2{margin:0}.overlay header button{border:0;background:transparent}.overlay label{margin-top:14px;display:grid;gap:6px;font-size:11px}.overlay input,.overlay select{height:39px;padding:0 8px;border:1px solid #c9d5d0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}fieldset{margin-top:16px}fieldset label{display:inline-flex;margin-right:14px;align-items:center;gap:5px}fieldset input{height:auto}.overlay footer{margin-top:20px;justify-content:flex-end;gap:7px}.overlay footer button{height:38px;padding:0 13px;border:1px solid #cbd7d2;background:white}.overlay footer .primary{border:0;background:#183129}@media(max-width:1000px){.task-layout{grid-template-columns:1fr}.task-layout aside{min-height:300px}}@media(max-width:650px){.tasks-page h1{font-size:31px}.tasks-page>header p{display:none}.task-list>article{grid-template-columns:44px 1fr auto}.next{grid-column:2}.actions{grid-column:3;grid-row:1}.grid{grid-template-columns:1fr}}</style>
